L["Changes |cFFFF0000will not|r be applied to the Cooldowns display."] = "Änderungen |cFFFF0000werden nicht|r auf die Anzeige „Abklingzeiten“ angewendet."
L[" |cFF00FF00Defensives|r"] = " |cFF00FF00Defensive|r"
L[" |cFFFF0000Defensives|r"] = " |cFFFF0000Defensive|r"
