L["Delete this Action List"] = "Diese Aktionsliste löschen"
L["Delete this action list?"] = "Diese Aktionsliste löschen?"
L["Entry"] = "Eintrag"
L["Select the entry to modify in this action list.\n\nEntries in red are disabled, have no action set, have a conditional error, or use actions that are disabled/toggled off."] = "Wähle den Eintrag dieser Aktionsliste, den du bearbeiten willst.\n\nRote Einträge sind deaktiviert, haben keine Aktion, einen Fehler in der Bedingung oder nutzen deaktivierte bzw. ausgeschaltete Aktionen."
L["Unassigned"] = "Nicht zugewiesen"
L["reset |cff00ccff%s|r"] = "|cff00ccff%s|r zurücksetzen"
L["unassigned"] = "nicht zugewiesen"
L["|cff00ccff%s|r default = |cffffd100%s|r"] = "|cff00ccff%s|r Standard = |cffffd100%s|r"
L["set |cff00ccff%s|r = |cffffd100%s|r"] = "|cff00ccff%s|r = |cffffd100%s|r setzen"
L["nothing"] = "nichts"
L["%s, if |cffffd100%s|r"] = "%s, wenn |cffffd100%s|r"
L["|cff00ccff(not set)|r"] = "|cff00ccff(nicht gesetzt)|r"
L["|cff00ccff(not found)|r"] = "|cff00ccff(nicht gefunden)|r"
L["Delete this entry?"] = "Diesen Eintrag löschen?"
L["If disabled, this entry will not be shown even if its criteria are met."] = "Wenn deaktiviert, wird dieser Eintrag nicht angezeigt, auch wenn seine Bedingungen erfüllt sind."
L["Action"] = "Aktion"
L["Select the action that will be recommended when this entry's criteria are met."] = "Wähle die Aktion, die empfohlen wird, wenn die Bedingungen dieses Eintrags erfüllt sind."
L["Buff Name"] = "Buffname"
L["Specify the buff to remove."] = "Lege den Buff fest, der entfernt werden soll."
L["Window Name"] = "Fenstername"
L["Specify the rotation window to open or close."] = "Lege das Rotationsfenster fest, das geöffnet oder geschlossen werden soll."
L["Action Name"] = "Aktionsname"
L["Specify the action to cancel; the result is that the addon will allow the channel to be removed immediately."] = "Lege die Aktion fest, die abgebrochen werden soll; das Addon erlaubt dann, die Kanalisierung sofort zu beenden."
L["Seconds"] = "Sekunden"
L["Max Energy"] = "Max. Energie"
L["When checked, this entry waits until the player has enough energy for the ability's full bonus from extra energy."] = "Wenn markiert, wartet dieser Eintrag, bis du genug Energie für den vollen Bonus der Fähigkeit durch zusätzliche Energie hast."
L["Caption"] = "Beschriftung"
L["Captions are |cFFFF0000very|r short descriptions that can appear on the icon of a recommended ability.\n\nThis can be useful for understanding why an ability was recommended at a particular time.\n\nRequires Captions to be enabled on each display."] = "Beschriftungen sind |cFFFF0000sehr|r kurze Erklärungen, die auf dem Symbol einer empfohlenen Fähigkeit erscheinen können.\n\nDamit verstehst du, warum eine Fähigkeit zu einem bestimmten Zeitpunkt empfohlen wurde.\n\nDafür müssen Beschriftungen in der jeweiligen Anzeige aktiviert sein."
L["Caption text should be 20 characters or less."] = "Beschriftungen sollten höchstens 20 Zeichen lang sein."
L["Label"] = "Bezeichnung"
L["Text shown on the recommendation while the Label Condition (if any) holds, e.g. a downranking note."] = "Text auf der Empfehlung, solange die Bezeichnungsbedingung (falls vorhanden) zutrifft, z. B. ein Hinweis auf einen niedrigeren Rang."
L["Label Condition"] = "Bezeichnungsbedingung"
L["If entered, the Label shows only while this is true."] = "Wenn gesetzt, erscheint die Bezeichnung nur, solange dies zutrifft."
L["Icon"] = "Symbol"
L["A texture file ID or path to show on the recommendation in place of the ability's icon while the Icon Condition (if any) holds. A path is resolved when the list loads; a bare file ID is not checked."] = "Eine Texturdatei-ID oder ein Pfad, der auf der Empfehlung statt des Symbols der Fähigkeit erscheint, solange die Symbolbedingung (falls vorhanden) zutrifft. Ein Pfad wird beim Laden der Liste geprüft; eine reine Datei-ID nicht."
L["Not a texture file; this line's icon is not overridden."] = "Keine Texturdatei; das Symbol dieser Zeile wird nicht ersetzt."
L["Icon Condition"] = "Symbolbedingung"
L["If entered, the Icon shows only while this is true."] = "Wenn gesetzt, erscheint das Symbol nur, solange dies zutrifft."
L["Condition"] = "Bedingung"
L["This allows you to provide text that explains this entry, which will show when you Pause and mouseover the ability to see why this entry was recommended."] = "Hier kannst du einen Text hinterlegen, der diesen Eintrag erklärt. Er erscheint, wenn du pausierst und mit der Maus über die Fähigkeit fährst, um zu sehen, warum dieser Eintrag empfohlen wurde."
L["Variable Name"] = "Variablenname"
L["Specify a name for this variable.  Variables must be lowercase with no spaces or symbols aside from the underscore."] = "Gib einen Namen für diese Variable an. Variablen müssen kleingeschrieben sein, ohne Leerzeichen oder Symbole außer dem Unterstrich."
L["Variables must be at least 3 characters in length."] = "Variablen müssen mindestens 3 Zeichen lang sein."
L["Invalid characters entered.  Try again."] = "Ungültige Zeichen eingegeben. Versuch es noch einmal."
L["Operation"] = "Operation"
L["Add Value"] = "Wert addieren"
L["Ceiling of Value"] = "Wert aufrunden"
L["Set Default Value"] = "Standardwert setzen"
L["Divide Value"] = "Wert dividieren"
L["Floor of Value"] = "Wert abrunden"
L["Maximum of Values"] = "Maximum der Werte"
L["Minimum of Values"] = "Minimum der Werte"
L["Modulo of Value"] = "Wert modulo"
L["Multiply Value"] = "Wert multiplizieren"
L["Raise Value to X Power"] = "Wert hoch X"
L["Reset to Default"] = "Auf Standard zurücksetzen"
L["Set Value"] = "Wert setzen"
L["Set Value If..."] = "Wert setzen, wenn ..."
L["Subtract Value"] = "Wert subtrahieren"
L["Not Set"] = "Nicht gesetzt"
L["Pool for Next Entry (%s)"] = "Für nächsten Eintrag poolen (%s)"
L["If checked, the addon will pool resources until the next entry has enough resources to use."] = "Wenn markiert, poolt das Addon Ressourcen, bis der nächste Eintrag genug Ressourcen hat."
L["Pooling Time"] = "Pooling-Zeit"
L["Specify the time, in seconds, as a number or as an expression that evaluates to a number.\nDefault is |cFFFFD1000.5|r.  An example expression would be |cFFFFD100energy.time_to_max|r."] = "Gib die Zeit in Sekunden an, als Zahl oder als Ausdruck, der eine Zahl ergibt.\nStandard ist |cFFFFD1000.5|r. Ein Beispielausdruck wäre |cFFFFD100energy.time_to_max|r."
L["Extra Pooling"] = "Zusätzliches Pooling"
L["Specify the amount of extra resources to pool in addition to what is needed for the next entry."] = "Lege fest, wie viele Ressourcen zusätzlich zu dem, was der nächste Eintrag braucht, gepoolt werden."
L["Conditions"] = "Bedingungen"
L["Specify Conditions that must be met for this action to be recommended or used in generating recommendations."] = "Lege die Bedingungen fest, die erfüllt sein müssen, damit diese Aktion empfohlen oder für Empfehlungen genutzt wird."
L["Value"] = "Wert"
L["Provide the value to store (or calculate) when this variable is invoked.\n\nIf Conditions are provided, this value is set when Conditions are met."] = "Gib den Wert an, der beim Aufruf dieser Variable gespeichert (oder berechnet) wird.\n\nSind Bedingungen angegeben, wird dieser Wert gesetzt, wenn sie erfüllt sind."
L["Value when Conditions are Not Met"] = "Wert, wenn Bedingungen nicht erfüllt sind"
L["Provide the value to store (or calculate) if Conditions are not met."] = "Gib den Wert an, der gespeichert (oder berechnet) wird, wenn die Bedingungen nicht erfüllt sind."
L["Display"] = "Anzeige"
L["Show Unused Modifiers (if applicable)"] = "Ungenutzte Modifikatoren anzeigen (falls zutreffend)"
L["If checked, additional modifiers that are not currently used by this entry."] = "Wenn markiert, werden zusätzliche Modifikatoren angezeigt, die dieser Eintrag derzeit nicht nutzt."
L["Cycle Targets"] = "Ziele durchgehen"
L["If checked, the addon will check each available target and show whether to switch targets."] = "Wenn markiert, prüft das Addon jedes verfügbare Ziel und zeigt, ob du das Ziel wechseln sollst."
L["Max Cycle Targets"] = "Max. Ziele zum Durchgehen"
L["If cycle targets is checked, the addon will check up to the specified number of targets."] = "Ist „Ziele durchgehen“ markiert, prüft das Addon bis zu so viele Ziele."
L["Check Movement"] = "Bewegung prüfen"
L["If checked, this entry can only be recommended when your character movement matches the setting."] = "Wenn markiert, kann dieser Eintrag nur empfohlen werden, wenn die Bewegung deines Charakters zur Einstellung passt."
L["Movement"] = "Bewegung"
L["If set, this entry can only be recommended when your movement matches the setting."] = "Wenn gesetzt, kann dieser Eintrag nur empfohlen werden, wenn deine Bewegung zur Einstellung passt."
L["Stationary"] = "Stehend"
L["Moving"] = "In Bewegung"
L["Use Off GCD"] = "Während GCD nutzen"
L["If checked, this entry can be checked even if the global cooldown (GCD) is active."] = "Wenn markiert, kann dieser Eintrag auch geprüft werden, während die globale Abklingzeit (GCD) läuft."
L["Use While Casting"] = "Beim Wirken nutzen"
L["If checked, this entry can be checked even if you are already casting or channeling."] = "Wenn markiert, kann dieser Eintrag auch geprüft werden, während du schon einen Zauber wirkst oder kanalisierst."
L["During Channel"] = "Während Kanalisierung"
L["If checked, this entry can only be used if you are channeling another spell."] = "Wenn markiert, kann dieser Eintrag nur genutzt werden, während du einen anderen Zauber kanalisierst."
L["Focus Tier"] = "Fokusstufe"
L["Timeline style: 0 is off; a tier (1 highest) makes this entry a focus candidate. When it is predicted within the focus horizon it takes the Now circle; the lowest tier wins, then the soonest."] = "Stil „Zeitleiste“: 0 ist aus; eine Stufe (1 am höchsten) macht diesen Eintrag zum Fokus-Kandidaten. Wird er innerhalb des Fokushorizonts vorhergesagt, bekommt er den Kreis „Jetzt“; die niedrigste Stufe gewinnt, dann die früheste."
L["Entry Cooldown"] = "Eintrags-Abklingzeit"
L["If set, this entry cannot be recommended unless this time has passed since the last time the ability was used."] = "Wenn gesetzt, kann dieser Eintrag erst empfohlen werden, wenn seit der letzten Nutzung der Fähigkeit so viel Zeit vergangen ist."
L["Test Conditions Immediately"] = "Bedingungen sofort prüfen"
L["If checked, the Conditions (above) must be met immediately for this action to be recommended or used."] = "Wenn markiert, müssen die Bedingungen (oben) sofort erfüllt sein, damit diese Aktion empfohlen oder genutzt wird."
L["Additional Immediate Criteria"] = "Zusätzliche Sofortkriterien"
L["If entered, these Immediate Criteria must be met before the Conditions above will be tested."] = "Wenn gesetzt, müssen diese Sofortkriterien erfüllt sein, bevor die Bedingungen oben geprüft werden."
L["List Name"] = "Listenname"
L["Action list names should be at least 2 characters in length."] = "Namen von Aktionslisten sollten mindestens 2 Zeichen lang sein."
L["There is already an action list by that name."] = "Es gibt bereits eine Aktionsliste mit diesem Namen."
L["Only alphanumeric characters and underscores can be used in list names."] = "In Listennamen sind nur Buchstaben, Ziffern und Unterstriche erlaubt."
L["Add List"] = "Liste hinzufügen"
L["Cancel"] = "Abbrechen"
L["Create New Entry"] = "Neuen Eintrag erstellen"
L["|cff777777<No message provided>|r"] = "|cff777777<Keine Nachricht angegeben>|r"
L["|cffa0a0ffAutomatic Stress Test:|r "] = "|cffa0a0ffAutomatischer Stresstest:|r "
L["|cffff0000WARNING:|r There are unresolved Warnings related to this priority. Please review before exporting."] = "|cffff0000WARNUNG:|r Es gibt ungelöste Warnungen zu dieser Priorität. Prüfe sie vor dem Exportieren."
L["|cffffff00NOTICE:|r There are unresolved Warnings since reloading the UI. These may not be related to this priority."] = "|cffffff00HINWEIS:|r Seit dem Neuladen des UI gibt es ungelöste Warnungen. Sie hängen eventuell nicht mit dieser Priorität zusammen."
L["|cff00ff00No warnings or errors detected!|r\n"] = "|cff00ff00Keine Warnungen oder Fehler gefunden!|r\n"
L["Stress Test Results"] = "Stresstest-Ergebnisse"
L["Toggles"] = "Schalter"
L["Toggles are keybindings that can be used to control which abilities may be recommended and where they are displayed."] = "Schalter sind Tastenbelegungen, mit denen du steuerst, welche Fähigkeiten empfohlen werden dürfen und wo sie erscheinen."
L["Damage Cooldowns"] = "Schadens-Abklingzeiten"
L["Toggle Major and Minor Cooldowns to ensure they are recommended at ideal times."] = "Schalte große und kleine Abklingzeiten um, damit sie zum idealen Zeitpunkt empfohlen werden."
L["Major Cooldowns"] = "Große Abklingzeiten"
L["Set a key to toggle recommendations of Major Cooldowns on or off."] = "Lege eine Taste fest, um Empfehlungen großer Abklingzeiten ein- oder auszuschalten."
L["Enable Major Cooldowns"] = "Große Abklingzeiten aktivieren"
L["If checked, abilities and items that require the |cFFFFD100Major Cooldowns|r toggle can be recommended.\n\nThis toggle generally applies to major damage abilities with cooldowns of 60 seconds or greater.\n\nAbilities may be added/removed from this toggle in |cFFFFD100Abilities|r and/or |cFFFFD100Gear and Items|r sections."] = "Wenn markiert, können Fähigkeiten und Gegenstände empfohlen werden, die den Schalter |cFFFFD100Große Abklingzeiten|r brauchen.\n\nDieser Schalter gilt meist für große Schadensfähigkeiten mit einer Abklingzeit von 60 Sekunden oder mehr.\n\nFähigkeiten kannst du diesem Schalter in den Bereichen |cFFFFD100Fähigkeiten|r und/oder |cFFFFD100Ausrüstung und Gegenstände|r hinzufügen oder entfernen."
L["Show in Separate %s Cooldowns Display"] = "In getrennter Anzeige %s Abklingzeiten zeigen"
L["If checked, abilities controlled by this toggle will be shown separately in your |W%s |cFFFFD100Major Cooldowns|r|w display when the toggle is enabled.\n\nThis is an experimental feature and may not work well for some specializations."] = "Wenn markiert, erscheinen von diesem Schalter gesteuerte Fähigkeiten getrennt in deiner Anzeige |W%s |cFFFFD100Große Abklingzeiten|r|w, solange der Schalter aktiv ist.\n\nDas ist eine experimentelle Funktion und funktioniert bei manchen Spezialisierungen eventuell nicht gut."
L["Active During %s"] = "Aktiv während %s"
L["If checked, when any %s effect is active, the |cFFFFD100Major Cooldowns|r toggle will be treated as enabled, even if unchecked."] = "Wenn markiert, gilt der Schalter |cFFFFD100Große Abklingzeiten|r als aktiv, solange ein %s-Effekt aktiv ist, auch wenn er nicht markiert ist."
L["If checked, when %s is active, the |cFFFFD100Major Cooldowns|r toggle will be treated as enabled, even if unchecked."] = "Wenn markiert, gilt der Schalter |cFFFFD100Große Abklingzeiten|r als aktiv, solange %s aktiv ist, auch wenn er nicht markiert ist."
L["Minor Cooldowns"] = "Kleine Abklingzeiten"
L["Set a key to toggle recommendations of Minor Cooldowns on or off."] = "Lege eine Taste fest, um Empfehlungen kleiner Abklingzeiten ein- oder auszuschalten."
L["Enable Minor Cooldowns"] = "Kleine Abklingzeiten aktivieren"
L["If checked, abilities that require the |cFFFFD100Minor Cooldowns|r toggle can be recommended.\n\nThis toggle generally applies to damage-boosting abilities with a cooldown of 30 to 60 seconds, or abilities that you may want to control separately from your major cooldowns.\n\nAbilities may be added/removed from this toggle in |cFFFFD100Abilities|r and/or |cFFFFD100Gear and Items|r sections."] = "Wenn markiert, können Fähigkeiten empfohlen werden, die den Schalter |cFFFFD100Kleine Abklingzeiten|r brauchen.\n\nDieser Schalter gilt meist für schadenssteigernde Fähigkeiten mit einer Abklingzeit von 30 bis 60 Sekunden oder für Fähigkeiten, die du getrennt von deinen großen Abklingzeiten steuern willst.\n\nFähigkeiten kannst du diesem Schalter in den Bereichen |cFFFFD100Fähigkeiten|r und/oder |cFFFFD100Ausrüstung und Gegenstände|r hinzufügen oder entfernen."
L["Auto-Enable when |cFFFFD100Major Cooldowns|r Active"] = "Automatisch an, wenn |cFFFFD100Große Abklingzeiten|r aktiv"
L["If checked, when |cFFFFD100Major Cooldowns|r are enabled (or auto-enabled), your |cFFFFD100Minor Cooldowns|r may be recommended even if the toggle itself is not checked."] = "Wenn markiert und |cFFFFD100Große Abklingzeiten|r aktiv (oder automatisch aktiv) sind, können deine |cFFFFD100Kleinen Abklingzeiten|r empfohlen werden, auch wenn ihr Schalter nicht markiert ist."
L["Set a key to toggle recommendations of Potions on or off."] = "Lege eine Taste fest, um Empfehlungen von Tränken ein- oder auszuschalten."
L["Enable Potions"] = "Tränke aktivieren"
L["If checked, abilities that require the |cFFFFD100Potions|r toggle can be recommended."] = "Wenn markiert, können Fähigkeiten empfohlen werden, die den Schalter |cFFFFD100Tränke|r brauchen."
L["If checked, when |cFFFFD100Major Cooldowns|r are enabled (or auto-enabled), your |cFFFFD100Potions|r may be recommended even if the toggle itself is not checked."] = "Wenn markiert und |cFFFFD100Große Abklingzeiten|r aktiv (oder automatisch aktiv) sind, können deine |cFFFFD100Tränke|r empfohlen werden, auch wenn ihr Schalter nicht markiert ist."
L["Toggle whether priorities that move to reach the next ability show it out of range."] = "Schaltet um, ob Prioritäten, die sich zur nächsten Fähigkeit bewegen, diese außer Reichweite zeigen."
L["Set a key to toggle Movement on or off."] = "Lege eine Taste fest, um „Bewegung“ ein- oder auszuschalten."
L["Enable Movement"] = "Bewegung aktivieren"
L["If checked, a priority that moves to reach its next ability shows that ability while you are out of range, tinted as out of range. If unchecked, the ability is hidden until you are in range."] = "Wenn markiert, zeigt eine Priorität, die sich zu ihrer nächsten Fähigkeit bewegt, diese Fähigkeit schon außer Reichweite an, als außer Reichweite eingefärbt. Wenn nicht markiert, bleibt die Fähigkeit verborgen, bis du in Reichweite bist."
L["Interrupts and Defensives"] = "Unterbrechungen und Defensive"
L["Toggle Interrupts (and other utility) and Defensives as needed."] = "Schalte Unterbrechungen (und andere Hilfsfähigkeiten) und defensive Fähigkeiten nach Bedarf um."
L["Set a key to toggle recommendations of Interrupts (or utility abilities) on or off."] = "Lege eine Taste fest, um Empfehlungen von Unterbrechungen (oder Hilfsfähigkeiten) ein- oder auszuschalten."
L["Enable Interrupts"] = "Unterbrechungen aktivieren"
L["If checked, abilities that require the |cFFFFD100Interrupts|r toggle can be recommended"] = "Wenn markiert, können Fähigkeiten empfohlen werden, die den Schalter |cFFFFD100Unterbrechungen|r brauchen"
L["Show in Separate %s Interrupts Display"] = "In getrennter Anzeige %s Unterbrechungen zeigen"
L["If checked, abilities that require the |cFFFFD100Interrupts|r toggle will be shown separately in your %s Interrupts display."] = "Wenn markiert, erscheinen Fähigkeiten, die den Schalter |cFFFFD100Unterbrechungen|r brauchen, getrennt in deiner Anzeige %s Unterbrechungen."
L["Interrupt Timing"] = "Unterbrechungszeitpunkt"
L["By default, interrupts are recommended when an enemy's cast has 0.25 seconds (or less) remaining.\n\nIf set to 2, an interrupt could be recommended when the cast has less than 2 seconds remaining."] = "Standardmäßig werden Unterbrechungen empfohlen, wenn der Zauber eines Gegners noch 0,25 Sekunden (oder weniger) läuft.\n\nBei 2 kann eine Unterbrechung empfohlen werden, wenn der Zauber noch weniger als 2 Sekunden läuft."
L["Set a key to toggle recommendations of Defensives on or off.\n\nThis toggle applies primarily to Tank specializations."] = "Lege eine Taste fest, um Empfehlungen defensiver Fähigkeiten ein- oder auszuschalten.\n\nDieser Schalter gilt vor allem für Tank-Spezialisierungen."
L["Enable Defensives"] = "Defensive aktivieren"
L["If checked, abilities that require the |cFFFFD100Defensives|r toggle can be recommended.\n\nThis toggle applies primarily to Tank specializations."] = "Wenn markiert, können Fähigkeiten empfohlen werden, die den Schalter |cFFFFD100Defensive|r brauchen.\n\nDieser Schalter gilt vor allem für Tank-Spezialisierungen."
L["Show in Separate %s Defensives Display"] = "In getrennter Anzeige %s Defensive zeigen"
L["If checked, defensive/mitigation abilities will be shown separately in your |W%s |cFFFFD100Defensives|r|w display.\n\nThis toggle applies primarily to Tank specializations."] = "Wenn markiert, erscheinen Defensiv- und Schadensminderungsfähigkeiten getrennt in deiner Anzeige |W%s |cFFFFD100Defensive|r|w.\n\nDieser Schalter gilt vor allem für Tank-Spezialisierungen."
L["Display Control"] = "Anzeigesteuerung"
L["Cycle through your preferred Display Modes using the keybinding you select."] = "Wechsle mit der gewählten Tastenbelegung durch deine bevorzugten Anzeigemodi."
L["Display Mode"] = "Anzeigemodus"
L["Pressing this binding will cycle your Display Mode through the options checked below."] = "Diese Taste wechselt deinen Anzeigemodus durch die unten markierten Optionen."
L["Select Display Mode"] = "Anzeigemodus wählen"
L["Select your Display Mode."] = "Wähle deinen Anzeigemodus."
L["Automatic"] = "Automatisch"
L["Single-Target"] = "Einzelziel"
L["AOE (Multi-Target)"] = "AoE (mehrere Ziele)"
L["Fixed Dual Display"] = "Doppelt (fest)"
L["Reactive Dual Display"] = "Doppelt (reaktiv)"
L["Select the |cFFFFD100Display Modes|r that you wish to use.  Each time you press your |cFFFFD100Display Mode|r keybinding, the addon will switch to the next checked mode."] = "Wähle die |cFFFFD100Anzeigemodi|r, die du nutzen willst. Bei jedem Druck auf deine Taste für |cFFFFD100Anzeigemodus|r wechselt das Addon zum nächsten markierten Modus."
L["(Default)"] = "(Standard)"
L["If checked, the Display Mode toggle can select Automatic mode.\n\nThe Primary display shows recommendations based upon the detected number of enemies (based on your specialization's options)."] = "Wenn markiert, kann der Schalter „Anzeigemodus“ den Modus „Automatisch“ wählen.\n\nDie Anzeige „Primär“ zeigt Empfehlungen anhand der erkannten Gegnerzahl (nach den Optionen deiner Spezialisierung)."
L["%s Uses Primary Display\n%s Recommendations based on Targets Detected"] = "%s Nutzt die Anzeige „Primär“\n%s Empfehlungen nach erkannten Zielen"
L["If checked, the Display Mode toggle can select Single-Target mode.\n\nThe Primary display shows recommendations as though you have one target (even if more targets are detected)."] = "Wenn markiert, kann der Schalter „Anzeigemodus“ den Modus „Einzelziel“ wählen.\n\nDie Anzeige „Primär“ zeigt Empfehlungen, als hättest du ein Ziel (auch wenn mehr Ziele erkannt sind)."
L["%s Uses Primary Display\n%s Recommendations based on 1 Target\n%s Useful when Focusing Damage on a High-Priority Enemy"] = "%s Nutzt die Anzeige „Primär“\n%s Empfehlungen für 1 Ziel\n%s Nützlich, wenn du Schaden auf einen wichtigen Gegner konzentrierst"
L["If checked, the Display Mode toggle can select AOE mode.\n\nThe Primary display shows recommendations as though you have at least |cFFFFD100%d|r targets (even if fewer are detected).\n\nThe number of targets is set in your specialization's options."] = "Wenn markiert, kann der Schalter „Anzeigemodus“ den Modus „AoE“ wählen.\n\nDie Anzeige „Primär“ zeigt Empfehlungen, als hättest du mindestens |cFFFFD100%d|r Ziele (auch wenn weniger erkannt sind).\n\nDie Zielanzahl legst du in den Optionen deiner Spezialisierung fest."
L["%s Uses Primary Display\n%s Recommendations based on at least |cFFFFD100%d|r Targets\n"] = "%s Nutzt die Anzeige „Primär“\n%s Empfehlungen für mindestens |cFFFFD100%d|r Ziele\n"
L["Dual"] = "Doppelt"
L["If checked, the Display Mode toggle can select Dual mode.\n\nThe Primary display shows single-target recommendations and the AOE display shows recommendations for |cFFFFD100%d|r or more targets (even if fewer are detected).\n\nThe number of AOE targets is set in your specialization's options."] = "Wenn markiert, kann der Schalter „Anzeigemodus“ den Modus „Doppelt“ wählen.\n\nDie Anzeige „Primär“ zeigt Einzelziel-Empfehlungen, die Anzeige „AoE“ Empfehlungen für |cFFFFD100%d|r oder mehr Ziele (auch wenn weniger erkannt sind).\n\nDie Zahl der AoE-Ziele legst du in den Optionen deiner Spezialisierung fest."
L["%s Uses Two Displays: Primary and AOE\n%s Primary Display's Recommendations based on 1 Target\n%s AOE Display's Recommendations based on at least |cFFFFD100%d|r Targets\n%s Useful for Ranged Specializations using Damage-Based Target Detection\n"] = "%s Nutzt zwei Anzeigen: „Primär“ und „AoE“\n%s Empfehlungen von „Primär“ für 1 Ziel\n%s Empfehlungen von „AoE“ für mindestens |cFFFFD100%d|r Ziele\n%s Nützlich für Fernkampf-Spezialisierungen mit schadensbasierter Zielerkennung\n"
L["If checked, the Display Mode toggle can select Reactive mode.\n\nThe Primary display shows single-target recommendations, while the AOE display remains hidden until/unless |cFFFFD100%d|r or more targets are detected."] = "Wenn markiert, kann der Schalter „Anzeigemodus“ den Modus „Reaktiv“ wählen.\n\nDie Anzeige „Primär“ zeigt Einzelziel-Empfehlungen, die Anzeige „AoE“ bleibt verborgen, bis |cFFFFD100%d|r oder mehr Ziele erkannt sind."
L["%s Uses Two Displays: Primary and AOE\n%s Primary Display's Recommendations based on 1 Target\n%s AOE Display Shown when |cFFFFD100%d|r+ Targets Detected"] = "%s Nutzt zwei Anzeigen: „Primär“ und „AoE“\n%s Empfehlungen von „Primär“ für 1 Ziel\n%s „AoE“ erscheint ab |cFFFFD100%d|r erkannten Zielen"
L["Troubleshooting"] = "Fehlerbehebung"
L["These keybindings help provide critical information when troubleshooting or reporting issues."] = "Diese Tastenbelegungen liefern wichtige Infos, wenn du Fehler suchst oder Probleme meldest."
L["Unpause"] = "Fortsetzen"
L["Pause"] = "Pause"
L["Set a key to pause processing of your action lists. Your current display(s) will freeze, and you can mouseover each icon to see information about the displayed action.\n\nThis will also create a Snapshot that can be used for troubleshooting and error reporting."] = "Lege eine Taste fest, um die Verarbeitung deiner Aktionslisten anzuhalten. Deine Anzeige(n) frieren ein, und du kannst mit der Maus über jedes Symbol fahren, um Infos zur angezeigten Aktion zu sehen.\n\nDabei entsteht auch ein Snapshot für Fehlersuche und Fehlerberichte."
L["Snapshot"] = "Snapshot"
L["Set a key to make a snapshot (without pausing) that can be viewed on the Snapshots tab.  This can be useful information for testing and debugging."] = "Lege eine Taste fest, um einen Snapshot (ohne Pause) zu erstellen, den du im Reiter „Snapshots“ ansehen kannst. Das ist nützlich zum Testen und Debuggen."
L["Custom Toggles"] = "Eigene Schalter"
L["These toggles allow for the creation of custom keybindings to control specific abilities."] = "Mit diesen Schaltern kannst du eigene Tastenbelegungen erstellen, die bestimmte Fähigkeiten steuern."
L["Custom #1"] = "Eigener #1"
L["Set a key to toggle your first custom set."] = "Lege eine Taste fest, um dein erstes eigenes Set umzuschalten."
L["Enable Custom #1"] = "„Eigener #1“ aktivieren"
L["If checked, abilities linked to Custom #1 can be recommended."] = "Wenn markiert, können Fähigkeiten empfohlen werden, die mit „Eigener #1“ verknüpft sind."
L["Custom #1 Name"] = "Name für „Eigener #1“"
L["Specify a descriptive name for this custom toggle."] = "Gib einen beschreibenden Namen für diesen eigenen Schalter an."
L["Custom #2"] = "Eigener #2"
L["Set a key to toggle your second custom set."] = "Lege eine Taste fest, um dein zweites eigenes Set umzuschalten."
L["Enable Custom #2"] = "„Eigener #2“ aktivieren"
L["If checked, abilities linked to Custom #2 can be recommended."] = "Wenn markiert, können Fähigkeiten empfohlen werden, die mit „Eigener #2“ verknüpft sind."
L["Custom #2 Name"] = "Name für „Eigener #2“"
L["Skeleton"] = "Skelett"
L["A rough skeleton of your current spec, for development purposes only."] = "Ein grobes Skelett deiner aktuellen Spezialisierung, nur für die Entwicklung."
L["Generate Skeleton"] = "Skelett erzeugen"
L["Warnings"] = "Warnungen"
L["Warning Identifier"] = "Warnungskennung"
L["Warning Information"] = "Warnungsinfo"
L["General"] = "Allgemein"
L["Welcome to Hekili Forever; includes general information and essential links."] = "Willkommen bei Hekili Forever; mit allgemeinen Infos und wichtigen Links."
L["Enables or disables the addon."] = "Aktiviert oder deaktiviert das Addon."
L["Hide Minimap Icon"] = "Minikartensymbol ausblenden"
L["If checked, the minimap icon will be hidden."] = "Wenn markiert, wird das Minikartensymbol ausgeblendet."
